package com.termux.app.workspace;
import android.app.*;import android.os.Looper;import android.view.*;import android.widget.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.shadows.ShadowAlertDialog;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
/** UI-only artificial library/profile routes: no native CLI, shell, authorization or service. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentStarNotesTest {
 static Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 static void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 static void call(Object o,String n)throws Exception{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}
 static View text(View v,String value){if(v instanceof TextView&&value.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View r=text(((ViewGroup)v).getChildAt(i),value);if(r!=null)return r;}return null;}
 static List<EditText> editors(View v){List<EditText> out=new ArrayList<>();if(v instanceof EditText)out.add((EditText)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)out.addAll(editors(((ViewGroup)v).getChildAt(i)));return out;}
 static AlertDialog dialog(){Shadows.shadowOf(Looper.getMainLooper()).idle();return ShadowAlertDialog.getLatestAlertDialog();}
 static String t(String s){return WorkspaceText.tr(s);}
 TermuxActivity activity()throws Exception{TermuxActivity a=Robolectric.buildActivity(TermuxActivity.class).get();a.setTheme(R.style.Theme_Termux_Black);a.setContentView(R.layout.activity_termux);set(a,"mTerminalView",a.findViewById(R.id.terminal_view));return a;}
 void check(String agent)throws Exception{for(String language:new String[]{"ru","en"}){
  TermuxActivity a=activity();WorkspaceLanguage.select(a,language);WorkspaceText.resources=WorkspaceLanguage.wrap(a).getResources();WorkspaceController c=new WorkspaceController(a);WorkspaceStore store=(WorkspaceStore)get(c,"store");AgentChatUi synthetic=null;java.io.File marker=null;AtomicInteger sends=new AtomicInteger();
  try{
   store.commands.clear();store.aliases.clear();store.notes.clear();WorkspaceStore.Command command=new WorkspaceStore.Command();command.name="Hidden command";command.command="never-run";store.commands.add(command);WorkspaceStore.Alias alias=new WorkspaceStore.Alias();alias.name="hidden_alias";alias.command="never-run-alias";store.aliases.add(alias);WorkspaceStore.Note note=new WorkspaceStore.Note();note.name="Favourite note";note.text=String.join("\n",Collections.nCopies(70,"Synthetic line"))+"\nlast line";note.favorite=true;store.notes.add(note);WorkspaceStore.Note other=new WorkspaceStore.Note();other.name="Other note";other.text="second";store.notes.add(other);store.save();store.awaitWrites();
   WorkspaceStore.Session p=new WorkspaceStore.Session();p.environment=agent.equals("codex")?"codex":"ubuntu";p.codexEnvironment="ubuntu";p.claudeAgent=agent.equals("claude");p.geminiAgent=agent.equals("gemini");p.aiAgent=agent.equals("opencode")?"opencode":"";
   if(agent.equals("codex")){marker=CodexChatControl.marker(a.getFilesDir(),p);marker.getParentFile().mkdirs();java.nio.file.Files.write(marker.toPath(),new byte[]{1});}
   ((AgentChatUi)get(c,"agentChatUi")).close();synthetic=new AgentChatUi(a,()->p,()->true,(owner,q)->{if(q.optString("op").equals("chat-send"))sends.incrementAndGet();return new JSONObject().put("ok",true).put("nativeChat",true).put("connected",true).put("session",p.id).put("rows",new JSONArray());});set(synthetic,"nativeChat",true);set(synthetic,"resolved",true);set(c,"agentChatUi",synthetic);call(c,"updateAgentComposer");AgentComposerControls controls=(AgentComposerControls)get(c,"composerControls");assertEquals(language.equals("ru")?"Заметки":"Notes",controls.star.getContentDescription().toString());controls.input.setText("unsent draft");
   controls.star.performClick();AlertDialog picker=dialog();assertNull(picker.getWindow().getDecorView().findViewWithTag("input-library-tabs"));assertNotNull(text(picker.getWindow().getDecorView(),t("Заметки")));assertNull(text(picker.getWindow().getDecorView(),"Alias"));assertEquals(2,picker.getListView().getAdapter().getCount());assertSame(note,picker.getListView().getAdapter().getItem(0));for(int i=0;i<2;i++)assertTrue(picker.getListView().getAdapter().getItem(i)instanceof WorkspaceStore.Note);EditText search=editors(picker.getWindow().getDecorView()).get(0);assertEquals(t("Найти заметку"),search.getHint().toString());search.setText("Other");assertSame(other,picker.getListView().getAdapter().getItem(0));search.setText("");
   picker.getListView().performItemClick(null,0,0);AlertDialog preview=dialog();assertNotNull(text(preview.getWindow().getDecorView(),note.text));for(String action:new String[]{"Вставить в сессию","Редактировать","Удалить"})assertNotNull(text(preview.getWindow().getDecorView(),t(action)));preview.getButton(-1).performClick();assertTrue(dialog().isShowing());assertEquals("unsent draft",controls.input.getText().toString());
   picker.getListView().performItemClick(null,0,0);preview=dialog();text(preview.getWindow().getDecorView(),t("Редактировать")).performClick();AlertDialog editor=dialog();editors(editor.getWindow().getDecorView()).get(1).setText("edited "+agent+language);editor.getButton(-1).performClick();store.awaitWrites();dialog();assertEquals("edited "+agent+language,note.text);assertEquals("unsent draft",controls.input.getText().toString());
   controls.star.performClick();picker=dialog();assertSame(note,picker.getListView().getAdapter().getItem(0));picker.getListView().performItemClick(null,0,0);text(dialog().getWindow().getDecorView(),t("Вставить в сессию")).performClick();dialog();assertEquals(note.text,controls.input.getText().toString());assertEquals(0,sends.get());
   controls.input.setText("new synthetic note");store.awaitWrites();byte[] beforeCancel=java.nio.file.Files.readAllBytes(new java.io.File(a.getFilesDir(),"workspace-v1.json").toPath());controls.star.performClick();picker=dialog();picker.getButton(-3).performClick();editor=dialog();assertEquals("new synthetic note",editors(editor.getWindow().getDecorView()).get(1).getText().toString());editors(editor.getWindow().getDecorView()).get(0).setText("Discarded note");editors(editor.getWindow().getDecorView()).get(1).setText("Discarded editor text");editor.getButton(-2).performClick();store.awaitWrites();assertEquals(2,store.notes.size());assertEquals("new synthetic note",controls.input.getText().toString());assertArrayEquals(beforeCancel,java.nio.file.Files.readAllBytes(new java.io.File(a.getFilesDir(),"workspace-v1.json").toPath()));
   controls.star.performClick();dialog().getButton(-3).performClick();editor=dialog();editors(editor.getWindow().getDecorView()).get(0).setText("Created note");editor.getButton(-1).performClick();store.awaitWrites();dialog();assertEquals(3,store.notes.size());WorkspaceStore restored=new WorkspaceStore(a,error->fail(error));try{assertEquals(3,restored.notes.size());assertTrue(restored.notes.stream().anyMatch(n->n.name.equals("Created note")&&n.text.equals("new synthetic note")));assertEquals(1,restored.commands.size());assertEquals("never-run",restored.commands.get(0).command);assertEquals(1,restored.aliases.size());assertEquals("never-run-alias",restored.aliases.get(0).command);}finally{restored.close();}
   controls.star.performClick();picker=dialog();picker.getListView().performItemClick(null,0,0);text(dialog().getWindow().getDecorView(),t("Удалить")).performClick();dialog().getButton(-2).performClick();assertEquals(3,store.notes.size());controls.star.performClick();picker=dialog();assertNull(picker.getWindow().getDecorView().findViewWithTag("input-library-tabs"));assertEquals(3,picker.getListView().getAdapter().getCount());assertSame(command,store.commands.get(0));assertSame(alias,store.aliases.get(0));assertEquals(0,sends.get());
  }finally{c.close();if(marker!=null)marker.delete();a.finish();}
 }}
 @Test public void codexNotesOnlyRuEnSaveReopenAndActions()throws Exception{check("codex");}
 @Test public void claudeNotesOnlyRuEnSaveReopenAndActions()throws Exception{check("claude");}
 @Test public void geminiNotesOnlyRuEnSaveReopenAndActions()throws Exception{check("gemini");}
 @Test public void openCodeNotesOnlyRuEnSaveReopenAndActions()throws Exception{check("opencode");}
 @Test public void ordinaryTerminalRetainsAllLibraryTabs()throws Exception{TermuxActivity a=activity();WorkspaceLanguage.select(a,"ru");WorkspaceText.resources=WorkspaceLanguage.wrap(a).getResources();WorkspaceController c=new WorkspaceController(a);try{call(c,"chooseInputCommand");AlertDialog p=dialog();assertNotNull(p.getWindow().getDecorView().findViewWithTag("input-library-tabs"));for(String label:new String[]{t("Команды"),"Alias",t("Заметки")})assertNotNull(label,text(p.getWindow().getDecorView(),label));}finally{c.close();a.finish();}}
}
